pub fn get_ui_map_assignments(ui_map_id: u32) -> Option<&'static [UiMapAssignment]> {
    let index = UI_MAP_ASSIGNMENTS.binary_search_by_key(&ui_map_id, |(id, _)| *id).ok()?;
    Some(UI_MAP_ASSIGNMENTS[index].1)
}
